-- Baseline schema for Path.
--
-- Generated from the JPA entities and written in portable SQL so the same migration
-- runs on H2 (PostgreSQL mode) and on PostgreSQL:
--   * bigint generated by default as identity  (PG 10+, H2 2.x)
--   * timestamp(6) with time zone              (both)
--   * enums stored as varchar + check          (deliberately not native enum types)
--
-- Hibernate runs with ddl-auto=validate, so any change here must be matched by an
-- entity change, and any entity change needs a new migration.

create table providers (
    id bigint generated by default as identity,
    slug varchar(64) not null unique,
    display_name varchar(128) not null,
    type varchar(32) not null check (type in ('OPENAI', 'ANTHROPIC')),
    base_url varchar(512) not null,
    api_key_cipher varchar(2048),
    enabled boolean not null,
    created_at timestamp(6) with time zone not null,
    primary key (id)
);

create table model_routes (
    id bigint generated by default as identity,
    public_model_id varchar(128) not null,
    provider_id bigint not null,
    upstream_model_id varchar(256) not null,
    input_price_per_million numeric(18,6),
    output_price_per_million numeric(18,6),
    cached_input_price_per_million numeric(18,6),
    cache_write_price_per_million numeric(18,6),
    priority integer not null,
    context_length integer,
    supports_streaming boolean not null,
    supports_tools boolean not null,
    enabled boolean not null,
    description varchar(512),
    primary key (id),
    constraint uk_route unique (public_model_id, provider_id, upstream_model_id)
);

create table client_keys (
    id bigint generated by default as identity,
    name varchar(128) not null,
    key_hash varchar(64) not null unique,
    key_prefix varchar(24) not null,
    key_suffix varchar(8) not null,
    enabled boolean not null,
    credit_limit_usd numeric(18,6),
    used_usd numeric(18,6) not null,
    rpm_limit integer not null,
    max_concurrent_requests integer,
    created_at timestamp(6) with time zone not null,
    last_used_at timestamp(6) with time zone,
    revoked_at timestamp(6) with time zone,
    primary key (id)
);

create table usage_records (
    id bigint generated by default as identity,
    created_at timestamp(6) with time zone not null,
    client_key_id bigint,
    client_key_name varchar(128),
    public_model_id varchar(128),
    provider_slug varchar(64),
    upstream_model_id varchar(256),
    prompt_tokens integer not null,
    completion_tokens integer not null,
    total_tokens integer not null,
    cached_input_tokens integer not null,
    cache_write_tokens integer not null,
    reasoning_tokens integer not null,
    audio_input_tokens integer not null,
    audio_output_tokens integer not null,
    input_cost_usd numeric(18,8),
    cached_input_cost_usd numeric(18,8),
    cache_write_cost_usd numeric(18,8),
    output_cost_usd numeric(18,8),
    cached_savings_usd numeric(18,8),
    cost_usd numeric(18,8),
    usage_estimated boolean not null,
    ttft_ms bigint,
    tokens_per_second numeric(10,2),
    upstream_request_id varchar(128),
    finish_reason varchar(32),
    attempts integer not null,
    fallback_from varchar(64),
    latency_ms bigint not null,
    streamed boolean not null,
    status varchar(16) not null check (status in ('SUCCESS', 'ERROR')),
    error_code varchar(64),
    error_message varchar(512),
    primary key (id)
);

create table idempotency_records (
    id bigint generated by default as identity,
    client_key_id bigint not null,
    idempotency_key varchar(64) not null,
    request_hash varchar(64) not null,
    status varchar(16) not null check (status in ('PENDING', 'COMPLETED')),
    http_status integer not null,
    content_type varchar(128),
    body text,
    created_at timestamp(6) with time zone not null,
    expires_at timestamp(6) with time zone not null,
    primary key (id),
    constraint uk_idempotency unique (client_key_id, idempotency_key)
);

create index ix_route_public on model_routes (public_model_id);
create index ix_usage_created on usage_records (created_at);
create index ix_usage_client on usage_records (client_key_id);
create index ix_usage_model on usage_records (public_model_id);
create index ix_idempotency_expiry on idempotency_records (expires_at);
